 "Content-Security-Policy":"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'none'"
};return msg;

const known=String(env.get("BLE_BMS_ADDRESSES")||"").toUpperCase()
 .split(/[,;\s]+/).filter(x=>/^[A-F0-9]{2}(:[A-F0-9]{2}){5}$/.test(x));
const states=global.get("jk_temperature_controls_confirmed")||{},now=Date.now();
const batteries=[...new Set(known)].map(address=>{
 const v=states[address],age=v?Math.floor((now-v.at)/1000):null;
 const confirmed=!!(v&&Number.isFinite(age)&&age>=0&&age<180);
 return {address,label:"Batterie "+address.slice(-5),confirmed,
  disabled:confirmed?v.disabled:null,age_seconds:confirmed?age:null};
});
msg.payload={manual_control_enabled:String(env.get("BLE_TEMP_CONTROL_ENABLED"))==="true",batteries};
msg.headers={"Content-Type":"application/json","Cache-Control":"no-store"};
return msg;

const p=msg.payload||{};
if(p.type!==1||p.crc_ok!==true||typeof p.raw_hex!=="string"||
   !/^[0-9a-fA-F]{600}$/.test(p.raw_hex))return null;
const address=String(p.address||"").toUpperCase(),b=Buffer.from(p.raw_hex,"hex");
if(!/^[A-F0-9]{2}(:[A-F0-9]{2}){5}$/.test(address)||b.length!==300||
 b.subarray(0,4).toString("hex")!=="55aaeb90"||b[4]!==1||
 b.subarray(0,299).reduce((a,x)=>(a+x)&255,0)!==b[299])return null;
const value=b.readUInt16LE(282),states=global.get("jk_temperature_controls_confirmed")||{};
states[address]={disabled:(value&0x0002)!==0,at:Date.now(),flags:value};
global.set("jk_temperature_controls_confirmed",states);
node.status({fill:"green",shape:"dot",text:address.slice(-5)+" paramètres reçus"});
return null;

const p=msg.payload||{},addr=String(p.address||"").toUpperCase();
const known=String(env.get("BLE_BMS_ADDRESSES")||"").toUpperCase().split(/[,;\s]+/);
function reject(code,reason){
 msg.statusCode=code;msg.payload={error:reason};
 msg.headers={"Content-Type":"application/json","Cache-Control":"no-store"};
 return [null,msg];
}
if(!known.includes(addr))return reject(403,"bms_not_configured");
if(!["refresh","set_temperature_disabled"].includes(p.action))return reject(400,"invalid_action");
if(p.action==="set_temperature_disabled"&&String(env.get("BLE_TEMP_CONTROL_ENABLED"))!=="true")
 return reject(403,"manual_control_disabled_in_addon_options");
if(p.action==="set_temperature_disabled"&&(typeof p.disable!=="boolean"||
  p.confirmation!=="I_UNDERSTAND_THERMAL_PROTECTION_RISK"))return reject(403,"explicit_confirmation_required");
const body={address:addr,action:p.action};
if(p.action==="set_temperature_disabled"){body.disable=p.disable;body.confirmation=p.confirmation;}
msg.method="POST";msg.url="http://127.0.0.1:1896/control";
msg.headers={"Content-Type":"application/json",
  "X-BLE-Bridge-Token":String(env.get("BLE_BRIDGE_TOKEN")||"")};
msg.payload=JSON.stringify(body);
return [msg,null];

const code=Number(msg.statusCode)||502;
let data;try{data=typeof msg.payload==="string"?JSON.parse(msg.payload):msg.payload;}
catch(_){data={error:"invalid_backend_reply"};}
msg.statusCode=code;msg.payload=data;
msg.headers={"Content-Type":"application/json","Cache-Control":"no-store"};
return msg;
